globalThis.ABBATE_I18N_MODERN=Object.freeze({...globalThis.ABBATE_I18N_MODERN,...{"50 Übungsfragen":{"en":"50 practice questions","uk":"50 тренувальних запитань","ru":"50 тренировочных вопросов","cs":"50 cvičných otázek","bg":"50 тренировъчни въпроса","hr":"50 pitanja za vježbu","da":"50 øvelsesspørgsmål","nl":"50 oefenvragen","et":"50 harjutusküsimust","fi":"50 harjoituskysymystä","fr":"50 questions d'entraînement","el":"50 ερωτήσεις εξάσκησης","hu":"50 gyakorlókérdés","ga":"50 ceist chleachtaidh","it":"50 domande di esercitazione","lv":"50 treniņa jautājumi","lt":"50 praktikos klausimų","mt":"50 mistoqsija ta' prattika","pl":"50 pytań ćwiczeniowych","pt":"50 perguntas de treino","ro":"50 de întrebări de exersare","sk":"50 cvičných otázok","sl":"50 vadbenih vprašanj","es":"50 preguntas de práctica","sv":"50 övningsfrågor"},"Wähle deinen Ausbildungsbereich. Alle sechs Bereiche enthalten Übungsfragen. Die fachliche Freigabe durch die Fahrschule steht noch aus.":{"en":"Choose your training area. All six areas contain practice questions. Technical approval by the driving school is still pending.","uk":"Вибери напрям навчання. Усі шість напрямів містять тренувальні запитання. Фахове схвалення автошколи ще очікується.","ru":"Выбери направление обучения. Все шесть направлений содержат тренировочные вопросы. Профессиональное одобрение автошколы ещё не получено.","cs":"Vyber si oblast výcviku. Všech šest oblastí obsahuje cvičné otázky. Odborné schválení autoškolou zatím chybí.","bg":"Избери област на обучение. Всички шест области съдържат тренировъчни въпроси. Професионалното одобрение от автошколата предстои.","hr":"Odaberi područje obuke. Svih šest područja sadrži pitanja za vježbu. Stručno odobrenje autoškole još se čeka.","da":"Vælg dit uddannelsesområde. Alle seks områder indeholder øvelsesspørgsmål. Køreskolens faglige godkendelse afventes.","nl":"Kies je opleidingsgebied. Alle zes gebieden bevatten oefenvragen. De vakinhoudelijke goedkeuring van de rijschool is nog niet gegeven.","et":"Vali oma koolitusvaldkond. Kõik kuus valdkonda sisaldavad harjutusküsimusi. Autokooli erialane heakskiit on veel ootel.","fi":"Valitse koulutusalueesi. Kaikki kuusi aluetta sisältävät harjoituskysymyksiä. Autokoulun asiantuntijahyväksyntä on vielä kesken.","fr":"Choisis ton domaine de formation. Les six domaines contiennent des questions d'entraînement. La validation technique par l'auto-école est encore en attente.","el":"Επίλεξε τον τομέα εκπαίδευσής σου. Και οι έξι τομείς περιέχουν ερωτήσεις εξάσκησης. Εκκρεμεί η έγκριση του περιεχομένου από τη σχολή οδηγών.","hu":"Válaszd ki a képzési területedet. Mind a hat terület gyakorlókérdéseket tartalmaz. Az autósiskola szakmai jóváhagyása még várat magára.","ga":"Roghnaigh do réimse oiliúna. Tá ceisteanna cleachtaidh i ngach ceann de na sé réimse. Tá faomhadh gairmiúil na scoile tiomána fós ar feitheamh.","it":"Scegli il tuo ambito di formazione. Tutti e sei gli ambiti contengono domande di esercitazione. L'approvazione tecnica dell'autoscuola è ancora in sospeso.","lv":"Izvēlies savu apmācības jomu. Visās sešās jomās ir treniņa jautājumi. Autoskolas profesionālais apstiprinājums vēl tiek gaidīts.","lt":"Pasirink mokymosi sritį. Visose šešiose srityse yra praktikos klausimų. Vairavimo mokyklos specialistų patvirtinimo dar laukiama.","mt":"Agħżel il-qasam tat-taħriġ tiegħek. Is-sitt oqsma kollha fihom mistoqsijiet ta' prattika. L-approvazzjoni teknika mill-iskola tas-sewqan għadha pendenti.","pl":"Wybierz obszar szkolenia. Wszystkie sześć obszarów zawiera pytania ćwiczeniowe. Zatwierdzenie merytoryczne przez szkołę jazdy jest jeszcze w toku.","pt":"Escolhe a tua área de formação. As seis áreas incluem perguntas de treino. A aprovação técnica pela escola de condução ainda está pendente.","ro":"Alege domeniul de instruire. Toate cele șase domenii conțin întrebări de exersare. Aprobarea tehnică de către școala de șoferi este încă în așteptare.","sk":"Vyber si oblasť výcviku. Všetkých šesť oblastí obsahuje cvičné otázky. Odborné schválenie autoškolou ešte chýba.","sl":"Izberi področje usposabljanja. Vseh šest področij vsebuje vadbena vprašanja. Strokovna potrditev avtošole še ni bila podana.","es":"Elige tu área de formación. Las seis áreas contienen preguntas de práctica. La aprobación técnica de la autoescuela está pendiente.","sv":"Välj ditt utbildningsområde. Alla sex områden innehåller övningsfrågor. Trafikskolans fackmässiga godkännande återstår."},"Ladungssicherung üben":{"en":"Practise cargo securing","uk":"Тренувати кріплення вантажу","ru":"Тренировать крепление груза","cs":"Procvičit zajištění nákladu","bg":"Упражнения за укрепване на товара","hr":"Vježbaj osiguranje tereta","da":"Øv lastsikring","nl":"Oefen ladingzekering","et":"Harjuta veose kinnitamist","fi":"Harjoittele kuorman varmistamista","fr":"S'entraîner à l'arrimage des charges","el":"Εξάσκηση στην ασφάλιση φορτίου","hu":"Rakományrögzítés gyakorlása","ga":"Cleachtaigh daingniú lasta","it":"Esercitati nel fissaggio del carico","lv":"Trenējies kravas nostiprināšanā","lt":"Praktikuok krovinio tvirtinimą","mt":"Ipprattika l-iżgurar tal-merkanzija","pl":"Ćwicz zabezpieczanie ładunku","pt":"Praticar a fixação da carga","ro":"Exersează fixarea încărcăturii","sk":"Precvičiť zaistenie nákladu","sl":"Vadi zavarovanje tovora","es":"Practicar la sujeción de la carga","sv":"Öva lastsäkring"}}});

